{
  "command": "ui_set_widget_properties",
  "params": {
    "widget_blueprint_path": "string (required) — Full path of the target Widget Blueprint",
    "widget_name": "string (required) — Name of the widget to set properties on",
    "properties": "record (optional) — Property values keyed by their real UE property name (e.g. \"Text\", \"ColorAndOpacity\", \"Font\"). Values may be nested objects for struct properties, arrays for colors/vectors, or an asset path string for object references.",
    "slot_props": "record (optional) — Layout properties applied to the widget’s PANEL SLOT rather than the widget: canvas (anchors/position/size/alignment/auto_size/z_order), box (fill/padding/alignment), grid (row/column/spans). Keys the slot type does not support come back in unknown_slot_props instead of being silently dropped."
  },
  "returns": "{succeeded, failed, failed_properties?}",
  "cost": "medium"
}

{
  "command": "ui_layout_snapshot",
  "params": {
    "widget_blueprint_path": "string (required) — Full path of the Widget Blueprint to lay out",
    "screen_width": "number (optional) — Resolution to lay out at. Defaults to the blueprint’s design-time size.",
    "screen_height": "number (optional) — Resolution to lay out at. Defaults to the blueprint’s design-time size.",
    "widget_names": "string (required)[] (optional) — Return only these exact widget names. Use this for targeted style/geometry reads on large trees.",
    "offset": "number (optional) — Zero-based widget offset for paginating production-sized trees.",
    "limit": "number (optional) — Widgets to return per page (maximum 50, matching the UE transport limit)."
  },
  "returns": "{widget_blueprint_path, screen_width, screen_height, layout_resolved, layout_error?, widget_count, widgets:[{name, class, x, y, width, height, depth, anchors?, text_info?, brush_info?}]}",
  "cost": "medium"
}

{
  "command": "ui_compile_widget",
  "params": {
    "widget_blueprint_path": "string (required) — Full path of the Widget Blueprint to compile",
    "save_on_success": "bool (optional, default: false) — Save the package on successful compile"
  },
  "returns": "{success, status, warnings, errors}",
  "cost": "high"
}

{
  "command": "ui_save_widget",
  "params": {
    "widget_blueprint_path": "string (required) — Full path of the Widget Blueprint to save",
    "compile_first": "bool (optional, default: false) — Run compile before saving"
  },
  "returns": "{saved_path, success, package_dirty_after_save}",
  "cost": "medium"
}
